// RAG Analytics Engine v3.2 - ROUTING UPDATE
// This version outputs ONLY to "Store Session Data" - no parallel connections
// Author: Enhanced by Claude for RamziRebai

const nowIso = () => new Date().toISOString();

// Enhanced field name cleaning with better sanitization
const cleanFieldName = (fieldName) => {
  if (!fieldName || typeof fieldName !== 'string') {
    return 'unknown_field';
  }

  let cleaned = fieldName
    .replace(/\n+/g, ' ')           // Replace newlines with space
    .replace(/\s+/g, ' ')           // Replace multiple spaces with single space
    .replace(/[^\w\s-]/g, '_')      // Replace special chars with underscore
    .trim();                        // Remove leading/trailing whitespace

  if (cleaned.length > 255) {
    cleaned = cleaned.substring(0, 255);
  }

  return cleaned || 'unknown_field';
};

// Helpers
const asNumber = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

const safeGet = (obj, path, defaultValue) => {
  try {
    if (!obj) return defaultValue;
    const value = path.split('.').reduce(
      (curr, key) => (curr != null && curr[key] !== undefined ? curr[key] : undefined),
      obj
    );
    return value !== undefined ? value : defaultValue;
  } catch {
    return defaultValue;
  }
};

// Calculate modification rate from user feedback analysis
const calculateModificationRate = (feedbackData) => {
  const totalFeedbackRequests = asNumber(feedbackData.total_feedback_requests, 0);
  const totalFieldsModified = asNumber(feedbackData.total_fields_modified, 0);

  if (totalFeedbackRequests === 0) return 0;
  return totalFieldsModified / totalFeedbackRequests;
};

// Get first input item
const firstItem = $input.first();
const baseJson = (firstItem && firstItem.json) ? firstItem.json : {};

// Extract raw data with better error handling
let rawData;
try {
  const candidate = baseJson.hasOwnProperty('body') ? baseJson.body : baseJson;

  if (candidate == null) {
    throw new Error('No request body found');
  }

  if (typeof candidate === 'string') {
    rawData = JSON.parse(candidate);
  } else if (typeof candidate === 'object') {
    rawData = candidate;
  } else {
    throw new Error('Unsupported body type');
  }
} catch (e) {
  return [{
    json: {
      error: 'CRITICAL_DATA_EXTRACTION_FAILURE',
      details: e.message,
      timestamp: nowIso(),
      processed_by: 'RamziRebai',
      workflow_version: '3.2'
    }
  }];
}

// Validate structure
if (!rawData || typeof rawData !== 'object' || !rawData.enhanced_monitoring_summary) {
  const availableKeys = rawData && typeof rawData === 'object' ? Object.keys(rawData) : [];
  return [{
    json: {
      error: 'INVALID_RAG_REPORT_STRUCTURE',
      details: `Missing enhanced_monitoring_summary. Available keys: ${availableKeys.join(', ')}`,
      timestamp: nowIso(),
      processed_by: 'RamziRebai',
      workflow_version: '3.2'
    }
  }];
}

// Extract components
const summary = rawData.enhanced_monitoring_summary || {};
const confidenceData = summary.confidence_analysis || {};
const feedbackData = summary.user_feedback_analysis || {};
const stepTimes = summary.step_times || {};
const fieldDetails = rawData.field_confidence_details || {};

// Session metadata
const sessionId = `rag_${Date.now()}_ramzi_v32_${Math.random().toString(36).substr(2, 8)}`;
const timestamp = nowIso();
const processingStartTime = Date.now();

// Extract configuration for better tracking
const runtimeConfig = summary.runtime_configuration || {};
const llmModel = runtimeConfig.LLM_MODEL || 'unknown';
const embeddingModel = runtimeConfig.EMBEDDING_MODEL || 'unknown';
const chunkSize = asNumber(runtimeConfig.CHUNK_SIZE, 0);
const chunkOverlap = asNumber(runtimeConfig.CHUNK_OVERLAP, 0);
const similarityTopK = asNumber(runtimeConfig.SIMILARITY_TOP_K, 0);

// File information
const inputFiles = summary.input_files || {};
const resumeFile = inputFiles.resume_file || 'unknown';
const applicationForm = inputFiles.application_form || 'unknown';

// PRIMARY METRICS
const overallConfidence = asNumber(confidenceData.overall_average, 0);
const confidenceHealthScore = Math.round(((overallConfidence || 0) / 0.6) * 100);
const totalFieldsProcessed = asNumber(confidenceData.total_fields_processed, 0);

// Field analytics with enhanced processing
const fieldAverages = confidenceData.field_averages || {};
const fieldAnalytics = Object.entries(fieldAverages).map(([originalFieldName, data]) => {
  try {
    const cleanedFieldName = cleanFieldName(originalFieldName);
    const confidenceScores = fieldDetails[originalFieldName] || [];
    const avgConf = asNumber(data.average, 0);
    const minConf = asNumber(data.min, 0);
    const maxConf = asNumber(data.max, 0);
    const variance = Math.abs(maxConf - minConf);
    const stability = avgConf > 0 ? Math.max(0, Math.min(1, 1 - variance / avgConf)) : 0;

    return {
      field_name: cleanedFieldName,
      original_field_name: originalFieldName,
      avg_confidence: Math.round(avgConf * 1000) / 1000,
      min_confidence: Math.round(minConf * 1000) / 1000,
      max_confidence: Math.round(maxConf * 1000) / 1000,
      confidence_variance: Math.round(variance * 1000) / 1000,
      stability_score: Math.round(stability * 1000) / 1000,
      sample_count: asNumber(data.count, 0),
      health_status: avgConf >= 0.6 ? 'HEALTHY' : avgConf >= 0.4 ? 'WARNING' : 'CRITICAL',
      needs_optimization: avgConf < 0.5 || variance > 0.15,
      confidence_scores: confidenceScores,
      processing_timestamp: timestamp
    };
  } catch (e) {
    return {
      field_name: cleanFieldName(originalFieldName),
      original_field_name: originalFieldName,
      avg_confidence: 0,
      min_confidence: 0,
      max_confidence: 0,
      confidence_variance: 0,
      stability_score: 0,
      sample_count: 0,
      health_status: 'ERROR',
      needs_optimization: true,
      confidence_scores: [],
      processing_timestamp: timestamp,
      error: e.message
    };
  }
});

// ENHANCED FEEDBACK METRICS
const totalFeedbackRequests = asNumber(feedbackData.total_feedback_requests, 0);
const totalFieldsModified = asNumber(feedbackData.total_fields_modified, 0);
const modificationRate = calculateModificationRate(feedbackData);
const feedbackEfficiency = Math.max(0, 1 - modificationRate);

// PERFORMANCE METRICS with step analysis
const totalExecutionTime = asNumber(summary.total_execution_time, 0);
const successRate = asNumber(summary.success_rate, 1);
const totalSteps = asNumber(summary.total_steps, 0);
const successfulSteps = asNumber(summary.successful_steps, 0);

// Enhanced step analysis
const stepTimeValues = Object.values(stepTimes)
  .map((v) => asNumber(v, NaN))
  .filter((v) => Number.isFinite(v));

let bottleneckStep = 'unknown';
let bottleneckTime = 0;
let averageStepTime = 0;

if (stepTimeValues.length > 0) {
  // Find bottleneck
  const [step, time] = Object.entries(stepTimes).reduce((a, b) =>
    (asNumber(stepTimes[a[0]], 0) > asNumber(stepTimes[b[0]], 0) ? a : b)
  );
  bottleneckStep = step;
  bottleneckTime = asNumber(time, 0);

  // Calculate average step time
  averageStepTime = stepTimeValues.reduce((a, b) => a + b, 0) / stepTimeValues.length;
}

const performanceVariance = stepTimeValues.length > 0
  ? Math.round(((Math.max(...stepTimeValues) - Math.min(...stepTimeValues)) / (averageStepTime || 1)) * 100)
  : 0;

// COMPREHENSIVE OUTPUT - includes all data for downstream processing
const output = {
  session_id: sessionId,
  timestamp: timestamp,

  // Configuration tracking (FIXED: now properly extracted)
  llm_model: llmModel,
  embedding_model: embeddingModel,
  chunk_size: chunkSize,
  chunk_overlap: chunkOverlap,
  similarity_top_k: similarityTopK,

  // File tracking
  resume_file: resumeFile,
  application_form: applicationForm,

  // Performance metrics (ENHANCED)
  execution_time: totalExecutionTime,
  success_rate: successRate,
  average_step_time: averageStepTime,
  bottleneck_step: bottleneckStep,
  bottleneck_time: bottleneckTime,
  performance_variance: performanceVariance,

  // Step-level timing for dashboard analysis
  step_times_json: JSON.stringify(stepTimes),

  // Confidence metrics (FIXED: total_fields_processed now included)
  overall_confidence: overallConfidence,
  confidence_health_score: confidenceHealthScore,
  total_fields_processed: totalFieldsProcessed,

  // Enhanced feedback metrics
  feedback_requests: totalFeedbackRequests,
  total_fields_modified: totalFieldsModified,
  modification_rate: modificationRate,
  feedback_efficiency: feedbackEfficiency,
  user_satisfaction: Math.round((1 - modificationRate) * 100),

  // Health assessment
  alert_severity: overallConfidence < 0.4 || totalExecutionTime > 180 || modificationRate > 0.5 ? 'CRITICAL' : 
                 overallConfidence < 0.6 || totalExecutionTime > 120 ? 'WARNING' : 'INFO',

  health_score: Math.round((confidenceHealthScore + Math.round((1 - modificationRate) * 100) + (successRate * 100)) / 3),

  // Metadata
  workflow_version: '3.2',
  processed_by: 'RamziRebai',
  processing_duration_ms: Date.now() - processingStartTime,

  // Raw data preservation for feedback processing and advanced analytics
  raw_data_json: JSON.stringify(rawData),

  // Field analytics for field processing
  field_analytics: fieldAnalytics,

  // Feedback data for feedback processing 
  feedback_iterations: feedbackData.feedback_iterations || [],

  // Enhanced monitoring summary for other nodes
  enhanced_monitoring_summary: summary
};

// CRITICAL: Return single output that goes ONLY to "Store Session Data"
// All other processing will happen after the session is stored
return [{ json: output }];

// Enhanced Field Data Processor - Fixed null handling

const nowIso = () => new Date().toISOString();
const asNumber = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

try {
  const items = $input.all();

  if (!items || items.length === 0) {
    return [];
  }

  const out = [];

  for (const it of items) {
    const base = it && it.json ? it.json : {};
    const fieldAnalytics = base.field_analytics;

    if (!Array.isArray(fieldAnalytics) || fieldAnalytics.length === 0) {
      continue;
    }

    const sessionId = base.session_id || `rag_${Date.now().toString(36)}`;
    const timestamp = base.timestamp || nowIso();

    // Extract configuration for each field record
    const llmModel = base.llm_model || 'unknown';
    const embeddingModel = base.embedding_model || 'unknown';
    const chunkSize = asNumber(base.chunk_size, 0);
    const chunkOverlap = asNumber(base.chunk_overlap, 0);
    const similarityTopK = asNumber(base.similarity_top_k, 0);
    const resumeFile = base.resume_file || 'unknown';

    for (let index = 0; index < fieldAnalytics.length; index++) {
      const field = fieldAnalytics[index] || {};

      try {
        const fieldName = field.field_name || `unknown_field_${index + 1}`;
        const originalFieldName = field.original_field_name || fieldName;
        const healthStatus = (typeof field.health_status === 'string' && field.health_status.length)
          ? field.health_status
          : 'UNKNOWN';

        // Individual confidence scores for time-series analysis
        const confidenceScores = Array.isArray(field.confidence_scores) ? field.confidence_scores : [];

        // FIXED: Handle field_error properly - use empty string instead of null
        const fieldError = field.error ? String(field.error) : '';

        // Create main field record
        const fieldRecord = {
          session_id: sessionId,
          timestamp: timestamp,
          field_name: fieldName,
          original_field_name: originalFieldName,
          avg_confidence: asNumber(field.avg_confidence, 0),
          min_confidence: asNumber(field.min_confidence, 0),
          max_confidence: asNumber(field.max_confidence, 0),
          confidence_variance: asNumber(field.confidence_variance, 0),
          stability_score: asNumber(field.stability_score, 0),
          health_status: healthStatus,
          needs_optimization: !!field.needs_optimization,
          sample_count: asNumber(field.sample_count, 0),

          // Configuration tracking per field
          llm_model: llmModel,
          embedding_model: embeddingModel,
          chunk_size: chunkSize,
          chunk_overlap: chunkOverlap,
          similarity_top_k: similarityTopK,
          resume_file: resumeFile,

          // Store confidence scores as JSON for detailed analysis
          confidence_scores_json: JSON.stringify(confidenceScores),

          processing_timestamp: field.processing_timestamp || timestamp,
          field_error: fieldError,  // FIXED: Now properly handles null/undefined

          // Add record type for routing
          record_type: 'field_analytics'
        };

        out.push({ json: fieldRecord });

        // Create individual confidence score records for time-series analysis
        confidenceScores.forEach((score, scoreIndex) => {
          const confidenceRecord = {
            session_id: sessionId,
            timestamp: timestamp,
            field_name: fieldName,
            confidence_score: asNumber(score, 0),
            score_sequence: scoreIndex + 1,
            llm_model: llmModel,
            embedding_model: embeddingModel,
            chunk_size: chunkSize,
            chunk_overlap: chunkOverlap,
            similarity_top_k: similarityTopK,
            record_type: 'confidence_score'
          };

          out.push({ json: confidenceRecord });
        });

      } catch (e) {
        // Error fallback for field record
        out.push({
          json: {
            session_id: sessionId,
            timestamp: timestamp,
            field_name: `error_field_${index + 1}`,
            original_field_name: `error_field_${index + 1}`,
            avg_confidence: 0,
            min_confidence: 0,
            max_confidence: 0,
            confidence_variance: 0,
            stability_score: 0,
            health_status: 'ERROR',
            needs_optimization: true,
            sample_count: 0,
            llm_model: llmModel,
            embedding_model: embeddingModel,
            chunk_size: chunkSize,
            chunk_overlap: chunkOverlap,
            similarity_top_k: similarityTopK,
            resume_file: resumeFile,
            confidence_scores_json: JSON.stringify([]),
            processing_timestamp: timestamp,
            field_error: e.message,  // Proper error message
            record_type: 'field_analytics'
          }
        });
      }
    }
  }

  return out;

} catch {
  return [];
}

// Enhanced Grafana Integration v3.0 - RAG Application Analytics
// Transforms RAG analytics data into comprehensive Grafana annotations and metrics
// Always returns an array of items: [{ json: {...} }]

const nowIso = () => new Date().toISOString();

try {
  const items = $input.all() || [];
  const out = [];

  for (const it of items) {
    const analytics = it?.json?.analytics;
    const rawData = analytics?.raw_log_data?.enhanced_monitoring_summary;

    if (!analytics || typeof analytics !== 'object') {
      out.push({ json: { warning: 'No analytics data available', time: Date.now(), data: {} } });
      continue;
    }

    const sessionId = analytics.session_id || `session_${Date.now()}`;
    const tsNow = Date.now();

    // Extract core performance metrics
    const totalExecutionTime = Number(rawData?.total_execution_time || analytics.performance?.total_execution_time || 0);
    const stepTimes = rawData?.step_times || {};
    const totalSteps = rawData?.total_steps || Object.keys(stepTimes).length;
    const successfulSteps = rawData?.successful_steps || totalSteps;
    const errorCount = rawData?.errors_count || 0;

    // Extract confidence metrics from raw data
    const confidenceAnalysis = rawData?.confidence_analysis || analytics.confidence_metrics;
    const overallConfidence = Math.round((confidenceAnalysis?.overall_average || analytics.confidence_metrics?.overall_confidence || 0) * 100);
    const fieldsProcessed = confidenceAnalysis?.total_fields_processed || analytics.confidence_metrics?.fields_processed || 0;
    const fieldAverages = confidenceAnalysis?.field_averages || {};

    // Calculate fields below threshold
    const threshold = analytics.runtime_config?.MIN_CONFIDENCE_THRESHOLD || 0.6;
    let fieldsBelowThreshold = 0;
    Object.values(fieldAverages).forEach(field => {
      if (field.average && field.average < threshold) {
        fieldsBelowThreshold++;
      }
    });

    // Extract feedback metrics
    const feedbackAnalysis = rawData?.user_feedback_analysis || analytics.feedback_metrics;
    const feedbackIterations = feedbackAnalysis?.total_feedback_requests || analytics.feedback_metrics?.total_feedback_iterations || 0;
    const modificationRate = Math.round((feedbackAnalysis?.modification_rate || analytics.feedback_metrics?.modification_rate || 0) * 100);

    // Extract system health metrics
    const systemHealth = analytics.system_health || {};
    const alertSeverity = String(systemHealth.alert_severity || 'INFO');
    const healthRating = String(systemHealth.health_rating || analytics.business_intelligence?.health_rating || 'UNKNOWN');
    const criticalIssuesCount = (systemHealth.critical_issues || []).length;
    const warningsCount = (systemHealth.warnings || []).length;

    // Extract business metrics
    const businessIntel = analytics.business_intelligence || {};
    const userSatisfaction = Number(businessIntel.user_satisfaction_score || 0);
    const systemEfficiency = Number(businessIntel.system_efficiency_score || 0);
    const processingQuality = Number(businessIntel.processing_quality_score || 0);

    // Extract runtime configuration
    const runtimeConfig = rawData?.runtime_configuration || analytics.runtime_config || {};
    const llmModel = runtimeConfig.LLM_MODEL || 'unknown';
    const embeddingModel = runtimeConfig.EMBEDDING_MODEL || 'unknown';
    const chunkSize = Number(runtimeConfig.CHUNK_SIZE || 0);
    const chunkOverlap = Number(runtimeConfig.CHUNK_OVERLAP || 0);
    const similarityTopK = Number(runtimeConfig.SIMILARITY_TOP_K || 0);

    // Calculate step-level metrics
    const stepMetrics = {};
    let bottleneckStep = 'unknown';
    let bottleneckTime = 0;

    for (const [step, time] of Object.entries(stepTimes)) {
      if (Number(time) > bottleneckTime) {
        bottleneckTime = Number(time);
        bottleneckStep = step;
      }
      stepMetrics[step.replace(/[^a-zA-Z0-9_]/g, '_')] = Number(time);
    }

    // Calculate performance variance
    const stepTimesArray = Object.values(stepTimes).map(Number);
    const avgStepTime = stepTimesArray.reduce((a, b) => a + b, 0) / stepTimesArray.length || 0;
    const variance = stepTimesArray.reduce((acc, time) => acc + Math.pow(time - avgStepTime, 2), 0) / stepTimesArray.length || 0;
    const performanceVariance = Math.round((Math.sqrt(variance) / avgStepTime) * 100) || 0;

    // Extract field-level confidence details
    const fieldConfidenceDetails = confidenceAnalysis?.field_confidence_details || rawData?.field_confidence_details || {};
    const fieldMetrics = {};

    for (const [fieldName, scores] of Object.entries(fieldConfidenceDetails)) {
      if (Array.isArray(scores) && scores.length > 0) {
        const avg = scores.reduce((a, b) => a + b, 0) / scores.length;
        const min = Math.min(...scores);
        const max = Math.max(...scores);
        const fieldKey = fieldName.replace(/[^a-zA-Z0-9_]/g, '_').toLowerCase();

        fieldMetrics[`field_${fieldKey}_avg_confidence`] = Math.round(avg * 100);
        fieldMetrics[`field_${fieldKey}_min_confidence`] = Math.round(min * 100);
        fieldMetrics[`field_${fieldKey}_max_confidence`] = Math.round(max * 100);
        fieldMetrics[`field_${fieldKey}_score_count`] = scores.length;
        fieldMetrics[`field_${fieldKey}_variance`] = Math.round(Math.sqrt(scores.reduce((acc, score) => acc + Math.pow(score - avg, 2), 0) / scores.length) * 100);
      }
    }

    const modelTag = llmModel.toLowerCase().replace(/[^a-z0-9]/g, '-');

    const grafanaAnnotation = {
      text: `🤖 RAG Analytics v3.0 by RamziRebai | ${alertSeverity} | Confidence: ${overallConfidence}% | Health: ${systemHealth.overall_health_score || 0}/100 | Satisfaction: ${userSatisfaction}% | Rating: ${healthRating} | Session: ${sessionId}`,
      tags: [
        'rag-system',
        'ramzirebai',
        'v3.0',
        alertSeverity.toLowerCase(),
        `health-${healthRating.toLowerCase()}`,
        `confidence-${overallConfidence < 40 ? 'critical' : overallConfidence < 60 ? 'warning' : 'good'}`,
        `satisfaction-${userSatisfaction < 70 ? 'poor' : userSatisfaction < 90 ? 'good' : 'excellent'}`,
        `model-${modelTag}`,
        `embedding-${embeddingModel.toLowerCase().replace(/[^a-z0-9]/g, '-')}`,
        `chunk-size-${chunkSize}`,
        `top-k-${similarityTopK}`
      ],
      time: tsNow - (totalExecutionTime * 1000),
      timeEnd: tsNow,
      data: {
        // Session & Identity
        session_id: sessionId,
        workflow_version: analytics.workflow_version || '3.0',
        processed_by: analytics.processed_by || 'RamziRebai',
        processing_timestamp: nowIso(),

        // Core Performance Metrics
        total_execution_time_seconds: totalExecutionTime,
        average_step_time: avgStepTime,
        total_steps: totalSteps,
        successful_steps: successfulSteps,
        success_rate: successfulSteps / totalSteps || 0,
        error_count: errorCount,
        bottleneck_step: bottleneckStep,
        bottleneck_time_seconds: bottleneckTime,
        performance_variance_percent: performanceVariance,

        // Confidence Metrics
        overall_confidence_percent: overallConfidence,
        confidence_health_score: Math.round((confidenceAnalysis?.overall_average || 0) * 100),
        fields_processed_total: fieldsProcessed,
        fields_below_threshold: fieldsBelowThreshold,
        confidence_threshold: threshold,

        // Field Performance Analysis
        highest_confidence_field: confidenceAnalysis?.highest_confidence_field?.field || 'unknown',
        highest_confidence_score: Math.round((confidenceAnalysis?.highest_confidence_field?.score || 0) * 100),
        lowest_confidence_field: confidenceAnalysis?.lowest_confidence_field?.field || 'unknown',
        lowest_confidence_score: Math.round((confidenceAnalysis?.lowest_confidence_field?.score || 0) * 100),

        // Feedback & User Interaction
        feedback_iterations: feedbackIterations,
        modification_rate_percent: modificationRate,
        feedback_efficiency: 100 - modificationRate,
        user_satisfaction_percent: userSatisfaction,

        // System Health
        alert_severity: alertSeverity,
        health_rating: healthRating,
        overall_health_score: systemHealth.overall_health_score || 0,
        critical_issues_count: criticalIssuesCount,
        warnings_count: warningsCount,

        // Business Intelligence
        system_efficiency_percent: systemEfficiency,
        processing_quality_percent: processingQuality,
        optimization_priority_count: businessIntel.optimization_priority_count || 0,

        // Runtime Configuration
        llm_model: llmModel,
        embedding_model: embeddingModel,
        chunk_size: chunkSize,
        chunk_overlap: chunkOverlap,
        similarity_top_k: similarityTopK,
        llm_temperature: Number(runtimeConfig.LLM_TEMPERATURE || 0),
        embedding_dimension: Number(runtimeConfig.EMBEDDING_DIMENSION || 0),
        max_retries: Number(runtimeConfig.MAX_RETRIES || 0),

        // Step-level Performance (for detailed analysis)
        ...stepMetrics,

        // Field-level Confidence Analysis (for field performance dashboards)
        ...fieldMetrics,

        // Additional Analytics
        fields_processed_per_second: fieldsProcessed / (totalExecutionTime || 1),
        processing_efficiency_score: Math.round((successfulSteps / totalSteps) * (1 - errorCount / totalSteps) * 100),
        confidence_distribution_excellent: confidenceAnalysis?.scores_distribution?.excellent || 0,
        confidence_distribution_good: confidenceAnalysis?.scores_distribution?.good || 0,
        confidence_distribution_moderate: confidenceAnalysis?.scores_distribution?.moderate || 0,
        confidence_distribution_poor: confidenceAnalysis?.scores_distribution?.poor || 0,

        // Resume & Application Context (if available)
        input_resume_file: rawData?.input_files?.resume_file || 'unknown',
        input_application_form: rawData?.input_files?.application_form || 'unknown',

        // Events & Monitoring
        events_processed: rawData?.events_processed || 0,
        low_confidence_events: (rawData?.event_log || []).filter(e => e.type === 'low_confidence_response').length
      }
    };

    out.push({ json: grafanaAnnotation });
  }

  // If no outputs produced, return a neutral warning item
  if (out.length === 0) {
    return [{ json: { warning: 'No input items processed', time: Date.now(), data: {} } }];
  }

  return out;
} catch (e) {
  // Safety net: always return an array with error details
  return [{ json: { error: 'grafana_integration_failed', message: e.message, stack: e.stack, time: Date.now() } }];
}

// Build Response v3.0 (hardened)
// Always returns an array of items: [{ json: {...} }]
// Maps over all incoming items and constructs a safe response per item.

const nowIso = () => new Date().toISOString();
const round = (n) => Math.round(Number(n) || 0);

try {
  const items = $input.all() || [];
  const out = [];

  for (const it of items) {
    const a = it?.json?.analytics;

    if (!a || typeof a !== 'object') {
      out.push({
        json: {
          status: 'ok',
          message: 'No analytics data available',
          timestamp: nowIso()
        }
      });
      continue;
    }

    const response = {
      status: 'success',
      message: 'RAG analytics processed successfully',
      timestamp: a.timestamp || nowIso(),
      processed_by: a.processed_by || 'unknown',
      workflow_version: a.workflow_version || '3.0',
      session_id: a.session_id || `session_${Date.now()}`,
      processing_duration_ms: a.processing_metadata?.duration_ms || 0,
      analytics_summary: {
        overall_confidence: round((a.confidence_metrics?.overall_confidence || 0) * 100),
        confidence_health_score: a.confidence_metrics?.confidence_health_score || 0,
        user_satisfaction: a.business_intelligence?.user_satisfaction_score || 0,
        system_health_score: a.system_health?.overall_health_score || 0,
        health_rating: a.business_intelligence?.health_rating || 'UNKNOWN',
        execution_time: round(a.performance?.total_execution_time || 0),
        feedback_iterations: a.feedback_metrics?.total_feedback_iterations || 0,
        alert_level: a.system_health?.alert_severity || 'INFO',
        fields_processed: a.confidence_metrics?.fields_processed || 0,
