// Robust Feedback Analytics Processor v3.2
// Fixed version that handles data extraction properly
// Author: Enhanced by Claude for RamziRebai

const nowIso = () => new Date().toISOString();
const asNumber = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

try {
  const items = $input.all();

  if (!items || items.length === 0) {
    console.log('No input items for feedback processing');
    return [];
  }

  const out = [];

  for (const it of items) {
    const base = it && it.json ? it.json : {};

    // Extract feedback data from multiple possible sources
    let feedbackIterations = [];
    let feedbackAnalysis = null;

    try {
      // Method 1: Direct from field_analytics (if passed through)
      if (base.feedback_iterations && Array.isArray(base.feedback_iterations)) {
        feedbackIterations = base.feedback_iterations;
      }

      // Method 2: From raw_data_json if available
      if ((!feedbackIterations || feedbackIterations.length === 0) && base.raw_data_json) {
        const rawData = typeof base.raw_data_json === 'string' 
          ? JSON.parse(base.raw_data_json) 
          : base.raw_data_json;

        feedbackIterations = rawData.enhanced_monitoring_summary?.user_feedback_analysis?.feedback_iterations || 
                           rawData.feedback_iterations || [];
        feedbackAnalysis = rawData.enhanced_monitoring_summary?.user_feedback_analysis || null;
      }

      // Method 3: Check if this data was passed from the analytics engine
      if ((!feedbackIterations || feedbackIterations.length === 0)) {
        // Look for feedback data in the original structure
        const enhancedSummary = base.enhanced_monitoring_summary;
        if (enhancedSummary && enhancedSummary.user_feedback_analysis) {
          feedbackIterations = enhancedSummary.user_feedback_analysis.feedback_iterations || [];
          feedbackAnalysis = enhancedSummary.user_feedback_analysis;
        }
      }

    } catch (e) {
      console.log('Error parsing feedback data:', e.message);
    }

    // Skip if no feedback iterations found
    if (!Array.isArray(feedbackIterations) || feedbackIterations.length === 0) {
      console.log('No feedback iterations found for session:', base.session_id);
      continue;
    }

    const sessionId = base.session_id || `rag_${Date.now().toString(36)}`;
    const baseTimestamp = base.timestamp || nowIso();
    const llmModel = base.llm_model || 'unknown';
    const embeddingModel = base.embedding_model || 'unknown';

    console.log(`Processing ${feedbackIterations.length} feedback iterations for session: ${sessionId}`);

    // Process each feedback iteration
    feedbackIterations.forEach((iteration, index) => {
      try {
        const fieldsModified = iteration.fields_modified || [];
        const feedbackDetails = iteration.feedback_details || [];
        const iterationNumber = asNumber(iteration.iteration_number, index + 1);

        // Handle timestamp - could be Unix timestamp or ISO string
        let iterationTimestamp;
        if (iteration.timestamp) {
          // If it's a number, assume Unix timestamp
          if (typeof iteration.timestamp === 'number') {
            iterationTimestamp = new Date(iteration.timestamp * 1000).toISOString();
          } else {
            iterationTimestamp = iteration.timestamp;
          }
        } else {
          iterationTimestamp = baseTimestamp;
        }

        // Calculate modification rate for this iteration
        const totalFeedbackRequests = feedbackDetails.length;
        const totalFieldsModified = fieldsModified.length;
        const modificationRate = totalFeedbackRequests > 0 ? 
          totalFieldsModified / totalFeedbackRequests : 0;

        const feedbackRecord = {
          session_id: sessionId,
          timestamp: iterationTimestamp,
          iteration_number: iterationNumber,
          fields_modified_count: totalFieldsModified,
          fields_modified_list: fieldsModified, // PostgreSQL will handle array conversion
          feedback_details: JSON.stringify(feedbackDetails),
          modification_rate: Math.round(modificationRate * 10000) / 10000, // 4 decimal places
          llm_model: llmModel,
          embedding_model: embeddingModel
        };

        console.log(`Created feedback record for iteration ${iterationNumber}:`, {
          session_id: sessionId,
          fields_modified: totalFieldsModified,
          feedback_requests: totalFeedbackRequests
        });

        out.push({ json: feedbackRecord });

      } catch (e) {
        console.log(`Error processing feedback iteration ${index}:`, e.message);
        // Create error record for debugging
        out.push({
          json: {
            session_id: sessionId,
            timestamp: baseTimestamp,
            iteration_number: index + 1,
            fields_modified_count: 0,
            fields_modified_list: [],
            feedback_details: JSON.stringify([]),
            modification_rate: 0,
            llm_model: llmModel,
            embedding_model: embeddingModel,
            error_message: e.message,
            error_iteration_data: JSON.stringify(iteration)
          }
        });
      }
    });
  }

  console.log(`Feedback processor completed. Generated ${out.length} records.`);
  return out;

} catch (e) {
  console.log('Critical error in feedback processor:', e.message);
  return [{
    json: {
      error: 'FEEDBACK_PROCESSING_FAILED',
      message: e.message,
      timestamp: nowIso()
    }
  }];
}

